xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	struct xfs_buf		*nbp;
	struct xfs_buf_map	*bmp;
	xfs_daddr_t		bno;
	int			nbytes = 0;
	int			i;

	for (i = 0, bmp = map; i < nmaps; i++, bmp++) {
		nbytes += (bmp->bm_len << BBSHIFT);
	}

	if (nbytes <= 0)
		return NULL;

	bno = map->bm_bn;

	bp = xfs_buf_find_rbtree(btp, bno, nbytes);
	if (bp) {
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_rele(bp);
			return NULL;
		}
		xfs_buf_lock(bp);
		return bp;
	}

	if (new_bp) {
		nbp = xfs_buf_alloc(btp, map, nmaps, flags);
		if (!nbp)
			return NULL;
		xfs_buf_insert(nbp);
		return nbp;
	}

	return NULL;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg		*btp,
	struct xfs_buf_map		*map,
	int				nmaps,
	xfs_buf_flags_t			flags,
	xfs_buf_t			*new_bp)
{
	struct xfs_buf		*bp;
	struct xfs_buf		*match = NULL;
	xfs_daddr_t		search_bn;
	xfs_off_t		search_len;
	int			error = 0;
	int			i;

	if (nmaps <= 0 || map == NULL)
		return NULL;

	search_bn = map->bm_bn;
	search_len = 0;

	for (i = 0; i < nmaps; i++) {
		if (map[i].bm_bn + BBTOB(map[i].bm_len) > search_bn)
			search_bn = map[i].bm_bn;
		search_len += BBTOB(map[i].bm_len);
	}

	if (!xfs_buf_search_alignment(btp, search_bn, search_len))
		return NULL;

	spin_lock(&btp->bt_lock);

	bp = xfs_buf_find_locked(btp, search_bn, search_len, flags, &match);

	if (match) {
		if (XFS_BUF_STALE(match)) {
			xfs_buf_stale(match);
			xfs_buf_relse(match);
			match = NULL;
		} else {
			xfs_buf_hold(match);
			error = xfs_buf_lock(match);
			if (error) {
				xfs_buf_relse(match);
				match = NULL;
			}
		}
	} else {
		if (new_bp) {
			new_bp->b_bn = search_bn;
			new_bp->b_bno = search_bn;
			new_bp->b_size = search_len;
			new_bp->b_flags = flags;
			xfs_buf_hold(new_bp);
			xfs_buf_insert(new_bp, btp);
			match = new_bp;
		}
	}

	spin_unlock(&btp->bt_lock);

	if (!match)
		return NULL;

	return match;
}

xfs_buf_t *
find_buffer(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_buf_t		*newbuf = NULL;
	struct xfs_mount	*mp = btp->bt_mount;
	struct xfs_perag	*pag;
	xfs_agnumber_t		agno = NULLAGNUMBER;
	xfs_daddr_t		startblock = 0;
	xfs_daddr_t		endblock = 0;
	xfs_daddr_t		blk;
	int			error;
	int			i;

	/*
	 * Calculate the total number of bytes to search for and check for
	 * alignment and corruption.
	 */
	for (i = 0, blk = 0; i < nmaps; i++) {
		startblock = map[i].bm_bn;
		if (map[i].bm_len == 0)
			continue;

		endblock = startblock + map[i].bm_len - 1;
		break;
	}

	if (i == nmaps)
		return NULL;

	pag = xfs_perag_get(mp, agno);

	/*
	 * Traverse the red-black tree of buffers to find a matching block number.
	 */
	bp = xfs_buf_find(btp, startblock, endblock, flags, &newbuf);

	if (bp == NULL) {
		if (new_bp == NULL) {
			new_bp = xfs_buf_alloc(btp, startblock, endblock, flags);
			if (new_bp == NULL)
				return NULL;
		} else {
			newbuf = new_bp;
		}

		/*
		 * Insert new buffer into the tree if no match is found.
		 */
		bp = xfs_buf_insert(btp, newbuf);
		if (bp == NULL) {
			xfs_buf_free(newbuf);
			return NULL;
		}
	}

	/*
	 * Handle stale buffers and lock the buffer.
	 */
	if (bp->b_flags & XBF_STALE) {
		error = xfs_btree_corrupt(btp, startblock);
		if (error) {
			xfs_buf_free(bp);
			return NULL;
		}
	}

	xfs_buf_lock(bp);

	/*
	 * Manage reference counting for buffers.
	 */
	xfs_buf_hold(bp);
	return bp;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	struct xfs_buf		*newbuf = NULL;
	struct xfs_btree	*tree = &btp->bt_buftree;
	struct xfs_buf_key	key;
	int			error;
	int			i;
	xfs_daddr_t		d;
	xfs_off_t		total_bytes = 0;

	/*
	 * Check for invalid parameters.
	 */
	if (!nmaps || !map) {
		return NULL;
	}

	/*
	 * Compute total bytes to read and verify alignment.
	 */
	for (i = 0; i < nmaps; i++) {
		d = map[i].bm_bn;
		if (XFS_BUF_MAP_IS_UOFFSET(&map[i])) {
			return NULL;
		}
		total_bytes += XFS_BUF_MAP_BLOCK_COUNT(&map[i]) * btp->bt_blocksize;
	}

	if (total_bytes <= 0) {
		return NULL;
	}

	/*
	 * Create a key to search for a buffer in the red-black tree.
	 */
	key.key = map[0].bm_bn;

	/*
	 * Search the red-black tree for a buffer with a matching block number.
	 */
	bp = xfs_buf_find_tree(tree, &key);

	/*
	 * If a buffer was found, check if it is valid and usable.
	 */
	if (bp) {
		/*
		 * Check for stale buffers.
		 */
		if (XFS_BUF_STALE(bp)) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			return NULL;
		}

		/*
		 * Lock the buffer and return it.
		 */
		if (xfs_buf_lock(bp)) {
			xfs_buf_relse(bp);
			return NULL;
		}

		return bp;
	}

	/*
	 * If no buffer was found and a new buffer was provided, insert it into the tree.
	 */
	if (new_bp) {
		newbuf = new_bp;
		error = xfs_buf_init(newbuf, map, nmaps, btp->bt_blocksize, flags);
		if (error) {
			return NULL;
		}

		if (xfs_buf_insert_tree(newbuf, tree, &key)) {
			return NULL;
		}

		return newbuf;
	}

	return NULL;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	struct xfs_buf		*found_bp = NULL;
	xfs_daddr_t		dblock;
	int64_t		nblocks = 0;
	int		i;
	int		error = 0;

	ASSERT(nmaps > 0);
	ASSERT(map != NULL);

	/*
	 * Compute the total number of blocks in the map and verify that it fits
	 * into a 64-bit variable. This also validates that the map does not
	 * contain negative block counts.
	 */
	for (i = 0; i < nmaps; i++) {
		nblocks += map[i].bm_len;
		if (nblocks < 0)
			return NULL;
	}

	dblock = map[0].bm_bn;

	/*
	 * Search the buffer cache for the specified block.  This is done by
	 * searching the red-black tree of buffers for the specified block number.
	 */
	found_bp = xfs_buf_find_in_tree(btp, dblock, nblocks);
	if (found_bp) {
		/*
		 * Check if the buffer is valid and not stale. If the buffer is
		 * stale, it should be invalidated and a new one inserted.
		 */
		if (found_bp->b_flags & XBF_STALE) {
			xfs_buf_stale(found_bp);
			xfs_buf_rele(found_bp);
			found_bp = NULL;
		} else {
			xfs_buf_hold(found_bp);
		}
	}

	if (!found_bp && (flags & XBF_CREATE)) {
		/*
		 * No buffer found, insert a new buffer into the cache.
		 */
		if (new_bp) {
			new_bp->b_bn = dblock;
			new_bp->b_bno = dblock;
			new_bp->b_count = nblocks;
			xfs_buf_insert_tree(btp, new_bp);
			found_bp = new_bp;
			xfs_buf_hold(found_bp);
		}
	}

	return found_bp;
}
